query:
query AiSocIndicators($first: Int!, $after: ID, $filters: FilterGroup) {
  stixCoreObjects(
    types: ["Indicator"]
    first: $first
    after: $after
    orderBy: updated_at
    orderMode: asc
    filters: $filters
  ) {
    edges {
      cursor
      node {
        id
        standard_id
        entity_type
        ... on Indicator {
          name
          description
          pattern
          pattern_type
          pattern_version
          revoked
          confidence
          indicator_types
          x_opencti_score
          x_opencti_main_observable_type
          created
          modified
          objectLabel { value }
          killChainPhases { kill_chain_name phase_name }
          externalReferences { edges { node { source_name url } } }
        }
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}
